const d = $json;
const trends = d.trends || [];
const dateStr = new Date().toISOString().slice(0,10);
let md = '# Weekly Industry Brief - ' + dateStr + '\n\n';
if (!trends.length) {
  md += '_No trends could be extracted this run (0 usable sources, or nothing groundable was found).\n\n';
} else {
  trends.forEach((t, i) => {
    md += '## ' + (i+1) + '. ' + t.trend_summary + '\n*Source:* ' + t.source_url + '\n*Why it matters for LeadFlow:* ' + t.relevance_note + '\n\n';
  });
}
if (d.sources_failed && d.sources_failed.length) {
  md += '\n---\n**Sources that failed this run:**\n' + d.sources_failed.map(f => '- ' + f.source_name + ' (' + f.status + ')').join('\n');
}
return [{ json: {
  markdown: md,
  subject: 'Weekly Industry Brief - ' + dateStr,
  trend_count: trends.length,
  sources_ok_count: d.sources_ok_count,
  sources_failed: d.sources_failed || [],
  trend_provider: d.trend_provider
}}];

const b = $('Build Markdown').first().json;
return [{ json: {
  trend_count: b.trend_count,
  sources_ok_count: b.sources_ok_count,
  sources_failed: b.sources_failed,
  trend_provider: b.trend_provider
}}];
